def V_k_basis(k):
    if k == 0:
        return []
    anchor = ctx["x_0"]-ctx["x_star"]
    if k == N_int:
        return [anchor]
    return [anchor, ctx[f"x_{k}"]-ctx["x_star"],
            f.grad(ctx[f"x_{k}"])-f.grad(ctx["x_star"]), f.grad(ctx[f"x_{k}"])]


def V_k_basis_labels(k):
    if k == 0:
        return []
    if k == N_int:
        return ["x0-star"]
    return ["x0-star", "xk-star", "grad_f_k-star", "grad_f_k"]

